def inventory(checklist=CHECKLIST):
    text = checklist.read_text()
    pattern = re.compile(r'^- \[([ x])\] \*\*(?:(P[012]) )?([A-Z]+-\d+)\b(.*)$', re.M)
    rows = []
    for checked, priority, identity, description in pattern.findall(text):
        status = 'partial_or_pending'
        evidence = []
        reason = 'Broader evaluation, implementation or reviewed evidence remains; see the original requirement.'
        if checked == 'x':
            status, reason = 'recorded_complete_scope', 'Original checklist completion scope retained; not release acceptance.'
        if identity in VERIFIED:
            path, reason = VERIFIED[identity]
            status = 'verified_synthetic_scope'
            evidence = [path, *EXTRA_EVIDENCE.get(identity, []),
                        EVIDENCE + 'batch-11/unit-tests-v5-final.txt', EVIDENCE + 'batch-11/integration-v1.txt']
        if identity.startswith(('AUDIO-', 'TTS-')):
            status = 'not_applicable_current_product'
            reason = 'No audio ingestion/transcription or spoken-output implementation in the supported text/document workflow; reconsider if added.'
            evidence = ['backend/app/ingest/reports.py', 'backend/app/api/endpoints/report_intake.py']
        elif priority == 'P2':
            status = 'deferred_conditional_research'
            reason = 'Conditional research; baseline quality and workload prerequisites are not met.'
        if identity in {f'ACCT-{i:02}' for i in range(1, 11)} or identity in {'PERF-06', 'PERF-12'}:
            status = 'external_account_evidence_required'
            reason = 'Owner reports slots 1/2 are different accounts with equal limits; slot 0 relationship, numeric entitlements, plans and other client traffic remain unknown; no split-admission policy enabled.'
        if identity in {'DATA-07', 'DATA-08', 'DATA-11', 'SCORE-06', 'CONF-03', 'EXP-10', 'NEXT-06'}:
            status = 'reviewed_dataset_or_frozen_selection_required'
            reason = 'No selected assembled candidate or fresh reviewed group-disjoint acceptance corpus; consumed synthetic cases cannot supply this evidence.'
        if checked == 'x' and identity in NEW_COMPLETED_SCOPES:
            path, reason = NEW_COMPLETED_SCOPES[identity]
            status, evidence = 'recorded_complete_scope', [path]
        if checked != 'x' and identity in BATCH18_PARTIAL:
            suffix, reason = BATCH18_PARTIAL[identity]
            status = 'partial_with_batch18_evidence'
            evidence = [EVIDENCE + 'batch-18/' + suffix]
        rows.append(dict(item_id=identity, priority=priority or 'next', status=status,
                         evidence=evidence, result_or_limitation=reason,
                         original_requirement=description.strip()))
    ids = [row['item_id'] for row in rows]
    if not rows or len(ids) != len(set(ids)):
        raise ValueError('Empty or duplicate checklist identities')
    for row in rows:
        for name in row['evidence']:
            if not Path(name).is_file():
                raise ValueError('Missing evidence: ' + name)
    return dict(version='checklist-disposition-v1', checklist_sha256=sha256(checklist.read_bytes()).hexdigest(),
                item_count=len(rows), status_counts=dict(Counter(row['status'] for row in rows)),
                release_accepted=False,
                scope='Every requirement inventoried; related tests verify only their stated synthetic/deterministic scope. Unknowns remain open.',
                items=rows)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    with args.output.open('x') as stream:
        stream.write(json.dumps(inventory(), indent=2) + '\n')
